public class PicklistProjectionProbe {
 public static Map<String,Object> run() {
  Map<String,Object> result=new Map<String,Object>();
  for(String fieldName:new List<String>{'Controlling__c','Dependent__c'}) {
   List<Object> entries=new List<Object>();
   Schema.DescribeFieldResult describe=Schema.getGlobalDescribe().get('ChoiceGrid__c').getDescribe().fields.getMap().get(fieldName).getDescribe();
   for(Schema.PicklistEntry entry:describe.getPicklistValues()) {
    String raw=JSON.serialize(entry);
    Map<String,Object> decoded=(Map<String,Object>)JSON.deserializeUntyped(raw);
    Map<String,Object> observed=new Map<String,Object>{'rawJSON'=>raw,'value'=>entry.getValue(),'active'=>entry.isActive(),'hasValidFor'=>decoded.containsKey('validFor'),'validFor'=>decoded.get('validFor')};
    if(decoded.get('validFor')!=null) {
     try {observed.put('hex',EncodingUtil.convertToHex(EncodingUtil.base64Decode((String)decoded.get('validFor'))));}
     catch(Exception ex){observed.put('decodeException',ex.getTypeName()+': '+ex.getMessage());}
    }
    entries.add(observed);
   }
   result.put(fieldName,entries);
  }
  result.put('unrelated',JSON.serialize(new Map<String,Object>{'validFor'=>'raw'}));
  return result;
 }
}

